def finite(v):return float(v) if math.isfinite(v) else None

def native_tree(v):
    if v is None or type(v) in (str,bool,int):return
    if type(v) is float:assert math.isfinite(v);return
    if type(v) is list:
        for x in v:native_tree(x)
        return
    assert type(v) is dict and all(type(k) is str for k in v)
    for x in v.values():native_tree(x)

def encode(v):
    native_tree(v)
    return (json.dumps(v,sort_keys=True,separators=(',',':'),allow_nan=False)+'\n').encode()

def norm(a):return float(np.linalg.norm(a))

def dot(a,b):return float(np.sum(a*b))

def pcg(A,b,diagonal,tolerance=.01,cap=100):
    """Positive blocks only; finite incomplete output is a preconditioner partial."""
    x=np.zeros_like(b);bn=norm(b);it=0;reason='iteration_allowance';checks=[]
    def action(v):
        if not np.all(np.isfinite(v)):return np.full_like(v,np.nan)
        try:return A(v)
        except (AssertionError,ValueError,FloatingPointError):return np.full_like(v,np.nan)
    def close(why):
        error=None
        if math.isfinite(bn) and bn>0 and np.all(np.isfinite(x)):
            ax=action(x)
            if np.all(np.isfinite(ax)):error=finite(norm(b-ax)/bn)
        return x,dict(ok=error is not None and error<=tolerance,error=error,iterations=it,
                      reason=why,true_checks=checks,finite_partial=bool(np.all(np.isfinite(x))))
    if bn==0 and np.all(b==0):return x,dict(ok=True,error=0.,iterations=0,reason='zero_rhs',true_checks=[],finite_partial=True)
    if not math.isfinite(bn) or bn<=0 or not np.all(np.isfinite(b)):
        return close('nonfinite_or_underflow_rhs')
    if not np.all(np.isfinite(diagonal)) or not np.all(diagonal>0):return close('positive_diagonal_failed')
    r=b.copy();z=r/diagonal;p=z.copy();rz=dot(r,z)
    for it in range(1,cap+1):
        if not math.isfinite(rz) or rz<=0:return close('positive_residual_breakdown')
        ap=action(p)
        if not np.all(np.isfinite(ap)):return close('nonfinite_positive_action')
        den=dot(p,ap)
        if not math.isfinite(den) or den<=0:return close('positive_block_breakdown')
        alpha=rz/den
        if not math.isfinite(alpha):return close('nonfinite_alpha')
        x+=alpha*p;r-=alpha*ap
        if not np.all(np.isfinite(x)) or not np.all(np.isfinite(r)):return close('nonfinite_inner_state')
        if norm(r)/bn<=tolerance or it%25==0:
            ax=action(x)
            if not np.all(np.isfinite(ax)):return close('nonfinite_true_action')
            r=b-ax;error=finite(norm(r)/bn);checks.append(dict(iteration=it,error=error))
            if error is not None and error<=tolerance:return close('true_residual')
            z=r/diagonal;p=z.copy();rz=dot(r,z);continue
        z=r/diagonal;new=dot(r,z)
        if not math.isfinite(new) or new<=0:return close('positive_update_breakdown')
        beta=new/rz
        if not math.isfinite(beta):return close('nonfinite_beta')
        p=z+beta*p;rz=new
    return close(reason)

def triangular(h,g,k):
    y=np.zeros(k)
    for i in range(k-1,-1,-1):
        if not math.isfinite(h[i,i]) or h[i,i]==0:return None
        y[i]=(g[i]-dot(h[i,i+1:k],y[i+1:k]))/h[i,i]
    return y if np.all(np.isfinite(y)) else None

def fgmres(A,b,M,seed,tolerance,restart=24,cap=240):
    """Right flexible preconditioning; original-denominator true residual only."""
    x=seed.copy();bn=norm(b);it=0;checks=[];prec=[]
    def action(v):
        if not np.all(np.isfinite(v)):return np.full_like(v,np.nan)
        try:return A(v)
        except (AssertionError,ValueError,FloatingPointError):return np.full_like(v,np.nan)
    def check(label):
        error=None
        if math.isfinite(bn) and bn>0 and np.all(np.isfinite(x)):
            ax=action(x)
            if np.all(np.isfinite(ax)):error=finite(norm(b-ax)/bn)
        checks.append(dict(iteration=it,error=error,reason=label));return error
    def close(label):
        error=check(label)
        return x,dict(ok=error is not None and error<=tolerance,error=error,iterations=it,
                      reason=label,true_checks=checks,preconditioner_calls=prec)
    if bn==0 and np.all(b==0):return np.zeros_like(b),dict(ok=True,error=0.,iterations=0,reason='zero_rhs',true_checks=[],preconditioner_calls=[])
    if not math.isfinite(bn) or bn<=0 or not np.all(np.isfinite(b)) or not np.all(np.isfinite(x)):
        return close('nonfinite_or_underflow_initial_state')
    initial=check('initial_true_residual')
    if initial is not None and initial<=tolerance:return close('authenticated_seed_true_residual')
    while it<cap:
        ax=action(x)
        if not np.all(np.isfinite(ax)):return close('nonfinite_restart_action')
        r=b-ax;beta=norm(r)
        if not math.isfinite(beta) or beta<=0:return close('restart_norm_breakdown')
        base=x.copy();v=[r/beta];z=[];h=np.zeros((restart+1,restart));g=np.zeros(restart+1)
        cs=np.zeros(restart);sn=np.zeros(restart);g[0]=beta
        for j in range(min(restart,cap-it)):
            try:zz,info=M(v[j])
            except (AssertionError,ValueError,FloatingPointError):return close('preconditioner_refusal')
            prec.append(dict(iteration=it+1,details=info))
            if not np.all(np.isfinite(zz)):return close('nonfinite_preconditioner_partial')
            z.append(zz);w=action(zz)
            if not np.all(np.isfinite(w)):return close('nonfinite_arnoldi_action')
            # Two modified Gram-Schmidt passes; no normal equations or dense field solve.
            for _ in range(2):
                for k in range(j+1):
                    a=dot(v[k],w);h[k,j]+=a;w-=a*v[k]
            sub=norm(w);h[j+1,j]=sub
            if not math.isfinite(sub) or not np.all(np.isfinite(h[:j+2,j])):
                return close('nonfinite_arnoldi_coefficient')
            if sub>0:v.append(w/sub)
            for k in range(j):
                aa=h[k,j];bb=h[k+1,j]
                h[k,j]=cs[k]*aa+sn[k]*bb;h[k+1,j]=-sn[k]*aa+cs[k]*bb
            gamma=math.hypot(h[j,j],h[j+1,j]);it+=1
            if not math.isfinite(gamma) or gamma==0:return close('rank_or_givens_breakdown')
            cs[j]=h[j,j]/gamma;sn[j]=h[j+1,j]/gamma;h[j,j]=gamma;h[j+1,j]=0
            g[j+1]=-sn[j]*g[j];g[j]=cs[j]*g[j]
            estimate=abs(g[j+1])/bn
            need=(it%25==0 or estimate<=tolerance or sub==0 or j==restart-1 or it==cap)
            if need:
                y=triangular(h,g,j+1)
                if y is None:return close('small_triangular_refusal')
                candidate=base.copy()
                with np.errstate(over='ignore',invalid='ignore'):
                    for k in range(j+1):candidate+=y[k]*z[k]
                if not np.all(np.isfinite(candidate)):return close('nonfinite_candidate_retained_previous_partial')
                x=candidate
                error=check('estimate_or_periodic_true_residual')
                if error is not None and error<=tolerance:return close('true_residual')
            if sub==0:return close('terminal_arnoldi_true_residual_failed')
        # x was updated at the cycle end; each restart recomputes the actual residual.
    return close('iteration_allowance')

class BlockPreconditioner:
    def __init__(self,model,x,root):
        self.model=model;self.root=root;self.forms=native.NativeForms(x,model.r,model.z)
        self.mask=model.mask[0];self.w=self.forms.w;self.sw=np.sqrt(self.w)
        assert np.array_equal(self.forms.mask,model.mask[[1,2]])
        self.shape=self.forms.shape;nr,nz=len(model.r),len(model.z)
        self.a=np.zeros((32,nr,nz));self.c=np.zeros_like(self.a);self.b=np.zeros_like(self.a)
        self.kdiag=np.zeros((2,nr,nz));self.pdiag=np.zeros((nr,nz));self.kpsi=np.zeros_like(self.pdiag)
        self.pressure=[]
        for rr,vol,shapes,vv,alpha,nn,t in self.forms.quad:
            val,_,_=core.interpolate(x[0],shapes)
            coefficient=-native.pressure_coefficient(val,model.ep,self.fixed(model))
            assert np.all(np.isfinite(coefficient)) and np.all(coefficient>0)
            self.pressure.append(coefficient)
            for n,dr,dz,i,j in shapes:
                sl=(slice(None),slice(i,nr-1+i),slice(j,nz-1+j));ss=(slice(i,nr-1+i),slice(j,nz-1+j))
                self.a[sl]+=vol*n*(t+2*alpha*vv[:,0]**2)
                self.c[sl]+=vol*n*(t+2*alpha*vv[:,1]**2)
                self.b[sl]+=vol*n*(2*alpha*vv[:,0]*vv[:,1])
                self.kdiag[(0,)+ss]+=vol*(dr*dr+dz*dz+n*n/rr**2)
                self.kdiag[(1,)+ss]+=vol*(dr*dr+dz*dz)
                self.kpsi[ss]+=vol*(dr*dr+dz*dz);self.pdiag[ss]+=vol*coefficient*n*n
        self.a+=4*core.ELL**2*self.kdiag[0];self.c+=4*core.ELL**2*self.kdiag[1]
        # Restrict the principal node block to free components BEFORE inversion.
        both=self.forms.mask[0]&self.forms.mask[1];onlya=self.forms.mask[0]&~self.forms.mask[1]
        onlyc=self.forms.mask[1]&~self.forms.mask[0];self.ia=np.zeros_like(self.a);self.ic=np.zeros_like(self.c);self.ib=np.zeros_like(self.b)
        assert np.all(np.isfinite(self.a)) and np.all(np.isfinite(self.b)) and np.all(np.isfinite(self.c))
        scale=np.maximum(self.a[:,both],self.c[:,both]);aa=self.a[:,both]/scale;cc=self.c[:,both]/scale;bb=self.b[:,both]/scale
        det=aa*cc-bb*bb;assert np.all(scale>0) and np.all(det>0)
        self.ia[:,both]=cc/(scale*det);self.ic[:,both]=aa/(scale*det);self.ib[:,both]=-bb/(scale*det)
        self.ia[:,onlya]=1/self.a[:,onlya];self.ic[:,onlyc]=1/self.c[:,onlyc]
        assert all(np.all(np.isfinite(t)) for t in (self.ia,self.ic,self.ib))
        self.weight=float(np.sum(self.w));self.remainder=abs(1-self.weight)
        self.diagonal=self.kpsi+self.pdiag;self.diagonal[~self.mask]=1
        assert np.all(self.diagonal>0) and np.all(np.isfinite(self.diagonal))
    @staticmethod
    def fixed(model):return model.fgmres_fixed
    def split(self,v):return np.stack([v[1::2],v[2::2]],axis=1)
    def join(self,p,v):
        out=np.zeros(self.model.shape);out[0]=p;out[1::2]=v[:,0];out[2::2]=v[:,1]
        out[~self.model.mask]=0;return out
    def B(self,p):
        out=np.zeros(self.shape)
        for rr,vol,shapes,*_ in self.forms.quad:
            _,gr,gz=core.interpolate(p,shapes);value=self.sw[:,None,None,None]*np.stack([gr,gz])[None]
            core.add(out,value,np.zeros_like(value),np.zeros_like(value),vol,shapes)
        out[:,~self.forms.mask]=0;return out
    def BT(self,v):
        out=np.zeros_like(self.pdiag)
        for rr,vol,shapes,*_ in self.forms.quad:
            val,_,_=core.interpolate(v,shapes);gr=np.sum(self.sw[:,None,None]*val[:,0],axis=0);gz=np.sum(self.sw[:,None,None]*val[:,1],axis=0)
            core.add(out,np.zeros_like(gr),gr,gz,vol,shapes)
        out[~self.mask]=0;return out
    def K(self,p):
        out=np.zeros_like(p)
        for rr,vol,shapes,*_ in self.forms.quad:
            _,gr,gz=core.interpolate(p,shapes);core.add(out,np.zeros_like(gr),gr,gz,vol,shapes)
        out[~self.mask]=0;return out
    def mass(self,p):
        out=np.zeros_like(p)
        for (rr,vol,shapes,*_),coefficient in zip(self.forms.quad,self.pressure):
            val,_,_=core.interpolate(p,shapes);core.add(out,coefficient*val,np.zeros_like(val),np.zeros_like(val),vol,shapes)
        out[~self.mask]=0;return out
    def upper_inverse(self,v):
        out=np.zeros_like(v);out[:,0]=self.ia*v[:,0]+self.ib*v[:,1];out[:,1]=self.ib*v[:,0]+self.ic*v[:,1]
        out[:,~self.forms.mask]=0;return out
    def upper(self,v):
        out=np.zeros_like(v);out[:,0]=self.a*v[:,0]+self.b*v[:,1];out[:,1]=self.b*v[:,0]+self.c*v[:,1]
        out[:,~self.forms.mask]=0;return out
    def P(self,p):return (self.weight+self.remainder)*self.K(p)-self.BT(self.upper_inverse(self.B(p)))+self.mass(p)
    def block_action(self,v):
        vv=self.split(v);p=v[0]
        return self.join(self.K(p)-self.mass(p)-self.BT(vv),self.forms.apply(vv,core.ELL)-self.B(p))
    def physical(self,rhs):
        t,i1=pcg(lambda y:self.forms.apply(y,core.ELL),self.split(rhs),self.forms.diage)
        if not np.all(np.isfinite(t)):return np.full_like(rhs,np.nan),dict(first_native=i1)
        p,ip=pcg(self.P,rhs[0]+self.BT(t),self.diagonal)
        if not np.all(np.isfinite(p)):return np.full_like(rhs,np.nan),dict(first_native=i1,scalar=ip)
        v,i2=pcg(lambda y:self.forms.apply(y,core.ELL),self.B(p),self.forms.diage)
        out=self.join(p,t+v)
        return out,dict(first_native=i1,scalar=ip,second_native=i2,
                        incomplete_finite_partials_used=not(i1['ok'] and ip['ok'] and i2['ok']))
    def __call__(self,rhs):
        value,info=self.physical(self.root*rhs);return self.root*value,info

def field_controls(block,H):
    ir=np.arange(block.model.shape[-2])[:,None];iz=np.arange(block.model.shape[-1])[None,:]
    p=np.sin(.17*(ir+1))*np.cos(.11*(iz+1));p[~block.mask]=0
    jj=np.arange(32)[:,None,None];v=np.empty(block.shape)
    v[:,0]=np.sin(.07*(jj+1)+.13*ir+.05*iz);v[:,1]=np.cos(.09*(jj+1)+.03*ir+.11*iz)
    v[:,~block.forms.mask]=0;dx=block.join(p,v)/block.root;other=block.join(.3*p,-.2*v)/block.root
    h=H(dx);hh=block.block_action(dx);b=block.B(p);bt=block.BT(v);u=block.upper_inverse(b)
    du=block.upper(v);dv=block.forms.apply(v,core.ELL);pp=block.P(p)
    kd=dot(p,block.K(p));md=dot(p,block.mass(p));pe=dot(p,pp)
    direct=(block.weight+block.remainder)*kd-2*dot(b,u)+dot(u,block.upper(u))+md
    gap=dot(v,du-dv);env=max(1e-30,abs(dot(v,du)),abs(dot(v,dv)))
    vals=[('whole_original_block_action',norm(h-hh)/max(1e-30,norm(h),norm(hh))),
          ('B_BT_exact_adjoint',abs(dot(b,v)-dot(p,bt))/max(1e-30,norm(b)*norm(v),norm(p)*norm(bt))),
          ('whole_original_symmetry',abs(dot(other,h)-dot(dx,H(other)))/max(1e-30,norm(other)*norm(h),norm(dx)*norm(H(other)))),
          ('positive_proxy_direct_energy',abs(pe-direct)/max(1e-30,(block.weight+block.remainder)*kd+md+2*abs(dot(b,u))+abs(dot(u,block.upper(u))))),
          ('upper_native_bound',max(0.,-gap)/env),('positive_scalar_proxy',max(0.,-pe)/max(1e-30,abs(pe),kd+md))]
    return [dict(name=n,error=finite(e),tolerance=2e-11,
                 signed_energy=finite(pe) if n=='positive_scalar_proxy' else None,
                 passed=math.isfinite(e) and e<=2e-11 and (pe>0 if n=='positive_scalar_proxy' else True)) for n,e in vals]

def inputs():return dict(PINS,**{STEM+'.md':PROTOCOL_SHA})
def auth():
    assert not AUTHOR_DRAFT and len(PROTOCOL_SHA)==64
    for n,h in inputs().items():assert sha(BASE/n)==h,('changed input',n)
    if core is not None:core.authenticate();assert core.PINS==CORE_INPUT_PINS

def publish(name,v):
    raw=encode(v);p=BASE/name
    with p.open('xb') as f:f.write(raw);f.flush();os.fsync(f.fileno())
    p.chmod(0o444);assert p.read_bytes()==raw;CREATED[name]=sha(p);return CREATED[name]

def closed_maps():
    for stem in ('CROSS_U_NGC3198_NONLINEAR_DISK_V001','CROSS_U_NGC3198_PARTIAL_RECOVERY_V002','CROSS_U_NGC3198_MINRES_RECOVERY_V003','CROSS_U_NONZERO_NATIVE_CURVATURE_SPLIT_V001',DIRECT):
        r=json.loads((BASE/(stem+'_RECEIPT.json')).read_text());native_tree(r)
        if stem==DIRECT:
            assert r['status']=='CLOSED' and r['owner']['pid']>0 and r['finished_utc']>r['owner']['started_utc']
            for n,h in r['pins'].items():assert sha(BASE/n)==h
        else:assert r['owner']=='root' and r['pid']>0 and r['closed']>r['started']
        for n,h in r['output_sha256'].items():assert sha(BASE/n)==h
    m=json.loads((BASE/(ACTIVE+'_MANIFEST.json')).read_text())
    assert m['owner']=='root' and m['pid']==57478 and m['no_automatic_resume'] is True and m['physics_changes']==[]
    assert m['source_sha256']==PINS['cross_u_ngc3198_direct_scalar_recovery_v005.py']
    assert m['completed_parent_cases_only']==['E1em05_HI0_H20','E1em05_HI0_H21','E1em05_HI1_H20']
    for n,h in m['input_sha256'].items():assert sha(BASE/n)==h
    return m

def selected():
    c=json.loads((BASE/BINDING['case_file']).read_text());native_tree(c)
    assert c['identity']['case']=='E1em05_HI0_H20' and c['status']=='NEWTON_ALLOWANCE' and len(c['history'])==40 and len(c['rows'])==43
    assert c['readout_qualified'] is False and all(v is False for v in c['physical_flags'].values())
    assert c['identity']['direct_scalar_source_sha256']==PINS['cross_u_ngc3198_direct_scalar_recovery_v005.py']
    assert c['identity']['direct_scalar_manifest_sha256']==PINS[ACTIVE+'_MANIFEST.json']
    assert len(c['own_checkpoints'])==41 and len(c['scalar_factor_checkpoints'])==40 and not c['scalar_failure_checkpoints']
    assert all(h['accepted'] is True and h['outer']==i for i,h in enumerate(c['history']))
    for group in ('own_checkpoints','scalar_factor_checkpoints','scalar_failure_checkpoints'):
        for rec in c[group]:
            assert PINS[rec['file']]==rec['sha256']==sha(BASE/rec['file'])
            assert PINS[rec['commit_file']]==rec['commit_sha256']==sha(BASE/rec['commit_file'])
            cp=json.loads((BASE/rec['commit_file']).read_text());assert cp['file']==rec['file'] and cp['sha256']==rec['sha256']
            if group=='own_checkpoints':assert cp['identity']==c['identity'] and cp['history_length']==rec['history_length'] and cp['partial_schema'] is None
            else:assert cp['metadata']==rec['metadata'] and cp['metadata']['identity']==c['identity'] and cp['metadata']['physical_state_checkpoint'] in c['own_checkpoints']
    assert all(c['own_checkpoints'][-1][k]==BINDING[k] for k in ('file','sha256','commit_file','commit_sha256'))
    return c

def checkpoint(tag,arrays,meta):
    schema={k:dict(shape=list(v.shape),dtype=str(v.dtype),finite=bool(np.all(np.isfinite(v)))) for k,v in arrays.items()}
    text=encode(dict(meta,owner=OWNER,schema=schema)).decode();data=json.loads(text);p=BASE/f'{STEM}_{len(RECORDS):05d}_{tag}.npz'
    with p.open('xb') as f:np.savez_compressed(f,metadata=text,**arrays);f.flush();os.fsync(f.fileno())
    p.chmod(0o444);CREATED[p.name]=sha(p);record=dict(file=p.name,sha256=CREATED[p.name],metadata=data)
    ch=publish(p.name+'.COMMIT.json',record);record=dict(record,commit_file=p.name+'.COMMIT.json',commit_sha256=ch);RECORDS.append(record)
    with np.load(p,allow_pickle=False) as n:
        assert str(n['metadata'])==text and set(n.files)==set(arrays)|{'metadata'}
        for k,v in arrays.items():assert np.array_equal(n[k],v,equal_nan=True)
    return record

def recheck():
    auth();closed_maps();selected()
    for n,h in CREATED.items():assert sha(BASE/n)==h
    for rec in RECORDS:
        assert sha(BASE/rec['file'])==rec['sha256'] and sha(BASE/rec['commit_file'])==rec['commit_sha256']
        assert json.loads((BASE/rec['commit_file']).read_text())=={k:v for k,v in rec.items() if k not in ('commit_file','commit_sha256')}
        with np.load(BASE/rec['file'],allow_pickle=False) as n:
            assert json.loads(str(n['metadata']))==rec['metadata'] and set(n.files)==set(rec['metadata']['schema'])|{'metadata'}
            for k,s in rec['metadata']['schema'].items():
                a=n[k];assert s==dict(shape=list(a.shape),dtype=str(a.dtype),finite=bool(np.all(np.isfinite(a))))
        if 'physical_state_checkpoint' in rec['metadata']:
            state=rec['metadata']['physical_state_checkpoint'];assert state in RECORDS and sha(BASE/state['file'])==state['sha256'] and sha(BASE/state['commit_file'])==state['commit_sha256']
    assert sha(__file__)==OWNER['source_sha256']

def split(x):return np.stack([x[1::2],x[2::2]],axis=1)
def join(model,p,v):
    out=np.zeros(model.shape);out[0]=p;out[1::2]=v[:,0];out[2::2]=v[:,1];out[~model.mask]=0;return out

def native_functional(model,x,dx=None):
    """Same four-point FE action, fixed potential; delta energy avoids Enew-Eold."""
    gradient=np.zeros((32,2,len(model.r),len(model.z)));energy=0.;change=0.;envelope=0.
    for rr,vol,shapes in model.quad:
        val,gr,gz=core.interpolate(x,shapes);v=np.stack([val[1::2],val[2::2]],axis=1)
        vr=np.stack([gr[1::2],gr[2::2]],axis=1);vz=np.stack([gz[1::2],gz[2::2]],axis=1)
        a=model.quartic;nn=np.sum(v*v,axis=1);alpha=a[:,None]
        source=model.sw[:,None]*np.stack([gr[0],gz[0]])[None]
        core.add(gradient,(1+a*nn)[:,None]*v-source+core.ELL**2*np.stack([v[:,0]/rr**2,np.zeros_like(v[:,1])],axis=1),core.ELL**2*vr,core.ELL**2*vz,vol,shapes)
        energy+=float(np.sum(vol*(np.sum(v*v,axis=1)/2+a*nn*nn/4-np.sum(source*v,axis=1)+core.ELL**2*(np.sum(vr*vr+vz*vz,axis=1)+v[:,0]**2/rr**2)/2)))
        if dx is not None:
            dv,dgr,dgz=core.interpolate(dx,shapes);u=np.stack([dv[1::2],dv[2::2]],axis=1)
            ur=np.stack([dgr[1::2],dgr[2::2]],axis=1);uz=np.stack([dgz[1::2],dgz[2::2]],axis=1)
            vu=np.sum(v*u,axis=1);uu=np.sum(u*u,axis=1)
            terms=[vu+uu/2,a*(nn*vu+nn*uu/2+vu*vu+vu*uu+uu*uu/4),-np.sum(source*u,axis=1),core.ELL**2*(np.sum(vr*ur+vz*uz,axis=1)+np.sum(ur*ur+uz*uz,axis=1)/2+(v[:,0]*u[:,0]+u[:,0]**2/2)/rr**2)]
            change+=sum(float(np.sum(vol*t)) for t in terms);envelope+=sum(float(np.sum(vol*abs(t))) for t in terms)
    gradient[:,~model.mask[[1,2]]]=0
    assert np.all(np.isfinite(gradient)) and all(math.isfinite(t) for t in (energy,change,envelope))
    return energy,gradient,change,envelope

def native_controls(model,x):
    r,_,_=model.residual(x);forms=native.NativeForms(x,model.r,model.z);ir,iz=np.indices(model.mask[0].shape);jj=np.arange(32)[:,None,None]
    d=np.zeros_like(x);d[1::2]=model.sw*model.xi[:,None,None]**2*np.sin(.07*(jj+1)+.13*ir+.05*iz);d[2::2]=model.sw*model.xi[:,None,None]**2*np.cos(.09*(jj+1)+.03*ir+.11*iz);d[~model.mask]=0
    E,g,_,_=native_functional(model,x);h=1e-4;_,gp,ep,envp=native_functional(model,x,h*d);_,gm,em,envm=native_functional(model,x,-h*d)
    fd=(ep-em)/(2*h);exact=dot(g,split(d));env=(envp+envm)/(2*h);e1=abs(fd-exact)/max(env,1e-30)
    xplus=x+h*d;xminus=x-h*d;_,gplus,_,_=native_functional(model,xplus);_,gminus,_,_=native_functional(model,xminus);dd=forms.apply(split(d),core.ELL)
    e2=norm((gplus-gminus)/(2*h)-dd)/max(norm(dd),1e-30);e0=norm(g-split(r))/max(norm(g)+norm(split(r)),1e-30)
    rows=[dict(name='same_native_original_gradient',error=finite(e0),tolerance=2e-11,passed=math.isfinite(e0) and e0<=2e-11),dict(name='stable_energy_directional_derivative',error=finite(e1),tolerance=1e-7,passed=math.isfinite(e1) and e1<=1e-7),dict(name='native_exact_Hessian_derivative',error=finite(e2),tolerance=1e-7,passed=math.isfinite(e2) and e2<=1e-7)]
    checkpoint('NATIVE_VARIATION_CONTROLS',dict(state=x,direction=d,original_native_gradient=split(r),independent_gradient=g,Hessian_action=dd,gradient_plus=gplus,gradient_minus=gminus),dict(kind='implementation_controls',controls=rows,energy=E,delta_energy_plus=ep,delta_energy_minus=em))
    return rows

class Run:
    def __init__(self,model,identity,scale):self.model=model;self.identity=identity;self.scale=scale;self.native_trials=0;self.D_failures=[];self.current_state_checkpoint=None
    def Dsolve(self,forms,b,label):
        y,info=pcg(lambda v:forms.apply(v,core.ELL),b,forms.diage,CONFIG['native_D_true_tolerance'],CONFIG['native_D_cap'])
        if not info['ok']:
            rec=checkpoint('NATIVE_D_FAILED',dict(rhs=b,partial=y,diagonal=forms.diage,mask=forms.mask),dict(kind='native_D_refusal',unaccepted=True,label=label,identity=self.identity,physical_state_checkpoint=self.current_state_checkpoint,linear=info,context=dict(CONTEXT)))
            self.D_failures.append(rec);raise ValueError('True original positive-native D solve refused')
        return y,info
    def equilibrate(self,x,label):
        x=x.copy();history=[];self.current_state_checkpoint=checkpoint('NATIVE_BEGIN',dict(state=x),dict(kind='native_equilibrium_initial',label=label,identity=self.identity,unaccepted=True))
        for it in range(CONFIG['native_equilibrium_cap']+1):
            CONTEXT.update(stage='native_equilibrium',label=label,iteration=it)
            r,pre,_=self.model.residual(x);rv=split(r);error=norm(rv/np.sqrt(split(pre)))/self.scale
            if not math.isfinite(error):
                checkpoint('NATIVE_NORM_FAILED',dict(state=x,residual=r,pre=pre),dict(kind='native_norm_refusal',unaccepted=True,label=label,physical_state_checkpoint=self.current_state_checkpoint,reason='Nonfinite normalized native residual; raw arrays retained'));return x,dict(ok=False,error=None,reason='nonfinite_native_norm',history=history)
            if math.isfinite(error) and error<=CONFIG['native_equilibrium_tolerance']:return x,dict(ok=True,error=error,iterations=it,history=history)
            if it==CONFIG['native_equilibrium_cap']:break
            forms=native.NativeForms(x,self.model.r,self.model.z);delta,lin=self.Dsolve(forms,-rv,[label,it]);full=join(self.model,np.zeros_like(x[0]),delta)
            _,g,_,_=native_functional(self.model,x);slope=dot(g,delta)
            if not math.isfinite(slope) or slope>=0:
                checkpoint('NATIVE_DIRECTION_FAILED',dict(state=x,residual=rv,direction=delta),dict(kind='native_descent_refusal',unaccepted=True,label=label,slope=finite(slope),linear=lin));return x,dict(ok=False,error=finite(error),reason='native_descent',history=history)
            accepted=False;row=dict(iteration=it,error=error,linear=lin,slope=slope,trials=[])
            for back in range(CONFIG['backtracks']):
                if self.native_trials>=CONFIG['native_trials_cap']:
                    checkpoint('NATIVE_TRIAL_CAP',dict(state=x,residual=rv,direction=delta),dict(kind='native_resource_refusal',unaccepted=True,label=label,linear=lin,history=history));return x,dict(ok=False,error=finite(error),reason='global_native_trial_cap',history=history)
                self.native_trials+=1;step=2.**(-back);candidate=x+step*full;raw=dict(state=x,candidate=candidate,native_direction=delta,residual=rv)
                try:
                    cr,cp=self.model.residual(candidate,False);raw['candidate_residual']=cr;raw['candidate_pre']=cp
                    _,_,de,env=native_functional(self.model,x,step*full);trial_error=norm(split(cr)/np.sqrt(split(pre)))/self.scale
                    accept=all(math.isfinite(t) for t in (trial_error,de,env)) and de<=1e-4*step*slope
                    trial=dict(backtrack=back,step=step,delta_energy=finite(de),uncanceled_envelope=finite(env),native_error=finite(trial_error),accepted=accept,reason=None if all(math.isfinite(t) for t in (trial_error,de,env)) else 'Nonfinite derived trial scalar; raw arrays retained')
                except (ValueError,AssertionError,FloatingPointError) as exc:accept=False;trial=dict(backtrack=back,step=step,accepted=False,reason=type(exc).__name__)
                rec=checkpoint('NATIVE_TRIAL',raw,dict(kind='native_equilibrium_trial',label=label,identity=self.identity,iteration=it,trial=trial,unaccepted=not accept));trial['checkpoint']=rec;row['trials'].append(trial)
                if accept:
                    x=candidate;self.current_state_checkpoint=checkpoint('NATIVE_ACCEPTED',dict(state=x),dict(kind='native_accepted',label=label,identity=self.identity,iteration=it+1,trial_checkpoint=rec));accepted=True;break
            row['accepted']=accepted;history.append(row)
            if not accepted:return x,dict(ok=False,error=finite(error),reason='native_globalization',history=history)
        checkpoint('NATIVE_EQUILIBRIUM_FAILED',dict(state=x,residual=rv),dict(kind='native_equilibrium_refusal',unaccepted=True,label=label,history=history))
        return x,dict(ok=False,error=finite(error),reason='native_Newton_allowance',history=history)

class ScalarInverse(BlockPreconditioner):
    def prepare(self,x):
        self.arrays={};proxy=direct.Proxy(self.model,x,self.fixed(self.model));band,self.free=direct.assembly(proxy,self.arrays);self.controls=[]
        ir,iz=np.indices(self.mask.shape)
        for label,p in [('smooth',np.sin(.17*(ir+1))*np.cos(.11*(iz+1))),('alternating',(-1.)**(ir+iz)*np.sin(.07*(ir+iz+1)))]:
            p[~self.mask]=0;orig=self.P(p);actual=direct.band_action(band,p.ravel()[self.free]);env=(self.weight+self.remainder)*norm(self.K(p))+norm(self.BT(self.upper_inverse(self.B(p))))+norm(self.mass(p))
            self.arrays['original_'+label]=orig;self.arrays['assembled_'+label]=actual;assert math.isfinite(env) and env>0,'Proxy action envelope refused';er=norm(actual-orig.ravel()[self.free])/env
            self.controls.append(dict(name='original_proxy_band_'+label,error=finite(er),tolerance=2e-11,passed=math.isfinite(er) and er<=2e-11));self.arrays['original_'+label]=orig;self.arrays['assembled_'+label]=actual
        self.factor,self.factor_info=direct.factor_band(band,self.arrays)
        assert self.factor is not None and all(c['passed'] for c in self.controls)
    def scalar(self,b):
        arrays=dict(scalar_rhs=b.ravel()[self.free].copy());f,scale=self.factor
        try:
            error,history=direct.refined_solve(self,f,scale,self.free,arrays['scalar_rhs'],arrays,'scalar')
            info=dict(ok=math.isfinite(error) and error<=1e-10,error=finite(error),history=history)
            if not info['ok']:raise ValueError('Original scalar-P residual refused')
        except (ValueError,AssertionError,FloatingPointError):
            checkpoint('SCALAR_INVERSE_FAILED',arrays,dict(kind='scalar_P_refusal',factor_checkpoint=self.factor_record,physical_state_checkpoint=self.physical_state_checkpoint,identity=self.case_identity,unaccepted=True,context=dict(CONTEXT),traceback=traceback.format_exc()));raise
        p=np.zeros_like(b);p.ravel()[self.free]=arrays['scalar_solution'];return p,info

def solve(run,x):
    model=run.model;history=[];status='NATIVE_IMPLEMENTATION_FAILED'
    run.current_state_checkpoint=checkpoint('INPUT',dict(state=x),dict(kind='original_parent_state',identity=run.identity,parent_binding=BINDING))
    controls=native_controls(model,x)
    if not all(c['passed'] for c in controls):return x,status,history,controls
    x,eq=run.equilibrate(x,'initial_fixed_potential')
    if not eq['ok']:return x,'NATIVE_EQUILIBRIUM_FAILED',history,controls
    initial_eq=eq;status='NEWTON_ALLOWANCE'
    run.current_state_checkpoint=checkpoint('EQUILIBRATED_INITIAL',dict(state=x),dict(kind='outer_base',identity=run.identity,native_equilibrium=eq))
    for outer in range(CONFIG['newton_cap']):
        CONTEXT.update(outer=outer,stage='reduced_Newton');r,pre,H=model.residual(x);root=np.sqrt(pre);error=norm(r/root)/run.scale
        if not math.isfinite(error):
            checkpoint('ORIGINAL_NORM_FAILED',dict(state=x,residual=r,pre=pre),dict(kind='original_full_norm_refusal',identity=run.identity,unaccepted=True,reason='Nonfinite original normalized residual; raw arrays retained'));status='ORIGINAL_NORM_FAILED';break
        if error<=CONFIG['final_original_residual']:status='CONVERGED';break
        target=min(.5,max(1e-6,.5*math.sqrt(error)));block=None
        try:
            block=ScalarInverse(model,x,root);block.case_identity=run.identity;block.physical_state_checkpoint=run.current_state_checkpoint;block.prepare(x)
        except (ValueError,AssertionError,FloatingPointError):
            checkpoint('SCALAR_FACTOR_FAILED',getattr(block,'arrays',{}),dict(kind='scalar_factor_refusal',identity=run.identity,physical_state_checkpoint=run.current_state_checkpoint,outer=outer,unaccepted=True,controls=getattr(block,'controls',[]),factor=getattr(block,'factor_info',None),context=dict(CONTEXT),traceback=traceback.format_exc()));status='SCALAR_FACTOR_FAILED';break
        block.factor_record=checkpoint('SCALAR_FACTOR',block.arrays,dict(kind='scalar_proxy_factor',identity=run.identity,physical_state_checkpoint=run.current_state_checkpoint,outer=outer,controls=block.controls,factor=block.factor_info))
        controls+=block.controls
        if outer==0:controls+=field_controls(block,H)
        if not all(c['passed'] for c in controls):status='BLOCK_IMPLEMENTATION_FAILED';break
        forms=block.forms;rv=split(r);saved=dict(state=x,original_residual=r,whitening_pre=pre,whitening_root=root)
        try:
            t,first=run.Dsolve(forms,rv,['Schur_rhs',outer]);bred=-r[0]-block.BT(t);saved['native_rhs_response']=t;saved['reduced_physical_rhs']=bred;bn=bred/root[0]
            calls=[]
            def A(v):
                p=v/root[0];response,info=run.Dsolve(forms,block.B(p),['Schur_action',outer,len(calls)]);calls.append(info)
                return (block.K(p)-block.mass(p)-block.BT(response))/root[0]
            def M(v):
                p,info=block.scalar(root[0]*v);return root[0]*p,info
            dpwhite,lin=fgmres(A,bn,M,np.zeros_like(bn),target,restart=CONFIG['reduced_restart'],cap=CONFIG['reduced_cap']);saved['reduced_whitened_partial']=dpwhite
            dp=dpwhite/root[0];dv,last=run.Dsolve(forms,block.B(dp)-rv,['full_reconstruction',outer]);delta=join(model,dp,dv);saved['full_physical_direction']=delta
            hd=H(delta);saved['original_full_H_action']=hd;b=-r/root;cert=norm((hd+r)/root)/norm(b)
            row=dict(outer=outer,error=error,inexact_target=target,reduced_linear=lin,native_rhs_linear=first,native_action_linears=calls,native_reconstruction_linear=last,original_full_H_error=finite(cert),full_linear_pass=math.isfinite(cert) and cert<=target and lin['ok'])
            checkpoint('REDUCED_LINEAR',saved,dict(kind='reduced_linear_certificate',identity=run.identity,outer=outer,row=row,unaccepted=not row['full_linear_pass']))
        except (ValueError,AssertionError,FloatingPointError):
            checkpoint('REDUCED_LINEAR_FAILED',saved,dict(kind='reduced_linear_refusal',identity=run.identity,outer=outer,unaccepted=True,context=dict(CONTEXT),traceback=traceback.format_exc()));status='LINEAR_FAILED';break
        if not row['full_linear_pass']:history.append(row);status='LINEAR_FAILED';break
        accepted=False;row['trials']=[]
        for back in range(CONFIG['backtracks']):
            step=2.**(-back);candidate=x+step*delta
            try:
                model.clock(candidate[0]);candidate,eq=run.equilibrate(candidate,['outer_trial',outer,back])
                if not eq['ok']:trial=dict(backtrack=back,step=step,accepted=False,reason='native_equilibrium_refusal',native_equilibrium=eq)
                else:
                    cr,_=model.residual(candidate,False);ce=norm(cr/root)/run.scale;accepted=math.isfinite(ce) and ce<=(1-1e-4*step)*error
                    trial=dict(backtrack=back,step=step,accepted=accepted,original_full_error=finite(ce),native_equilibrium=eq)
            except (ValueError,AssertionError,FloatingPointError) as exc:accepted=False;trial=dict(backtrack=back,step=step,accepted=False,reason=type(exc).__name__)
            checkpoint('OUTER_TRIAL',dict(base_state=x,candidate=candidate,direction=delta),dict(kind='outer_trial',identity=run.identity,outer=outer,trial=trial,unaccepted=not accepted));row['trials'].append(trial)
            if accepted:x=candidate;row.update(step=step,candidate_error=ce);break
        row['accepted']=accepted;history.append(row)
        if not accepted:status='GLOBALIZATION_FAILED';break
        run.current_state_checkpoint=checkpoint('OUTER_ACCEPTED',dict(state=x),dict(kind='outer_accepted',identity=run.identity,outer=outer+1,history=history))
        print('NATIVE_ELIMINATION','NEWTON',outer+1,'ERROR',ce,'STEP',step,flush=True)
    return x,status,history,controls

def main():
    global np,core,native,direct,OWNER
    auth();assert not [p for p in BASE.glob(STEM+'_*') if p.name!='CROSS_U_NGC3198_NATIVE_ELIMINATION_RECOVERY_V006_REVIEWED_17.md'],'Existing runtime preserved';pm=closed_maps();parent=selected();source=sha(__file__)
    fixed=json.loads((BASE/'CROSS_U_NGC3198_NONLINEAR_DISK_V001_RESULT.json').read_text())['manifest']['fixed']
    np=importlib.import_module('numpy');core=importlib.import_module('cross_u_ngc3198_nonlinear_disk_v001');native=importlib.import_module('cross_u_nonzero_native_curvature_split_v001');native.np=np;native.core=core
    direct=importlib.import_module('cross_u_direct_scalar_proxy_controls_v001');direct.np=np;direct.core=core;direct.native=native;direct.auth();auth()
    OWNER=dict(owner='root',pid=os.getpid(),source_sha256=source,started=now());tick=time.monotonic()
    manifest=dict(owner=OWNER,input_sha256=inputs(),parent_batch_closed=False,parent_manifest=pm,only_parent_terminal_case=parent,parent_cases_scope=['E1em05_HI0_H20'],direct_controls_preserved=json.loads((BASE/(DIRECT+'_RESULT.json')).read_text()),physics_changes=[],numerical_configuration=CONFIG,qualification=PHYSICAL)
    publish(STEM+'_MANIFEST.json',manifest)
    with np.load(BASE/BINDING['file'],allow_pickle=False) as n:
        assert set(n.files)=={'state','identity','history','schema'};x=n['state'].copy()
        assert json.loads(str(n['identity']))==parent['identity'] and json.loads(str(n['history']))==parent['history'] and json.loads(str(n['schema']))==dict(history_length=40,partial_schema=None)
    old=parent['identity'];model=core.Model(np.array(old['r_kpc']),np.array(old['z_kpc']),32,old['eps'],fixed,core.density.profiles(old['hi_tail'],old['h2_tail']));model.fgmres_fixed=fixed
    assert x.shape==model.shape and np.all(np.isfinite(x)) and np.all(x[~model.mask]==0)
    identity=dict(old,native_elimination_source_sha256=source,native_elimination_manifest_sha256=CREATED[STEM+'_MANIFEST.json'],native_elimination_parent_binding=BINDING)
    _,pre0,_=model.residual(np.zeros(model.shape));scale=norm(model.rhs/np.sqrt(pre0));assert math.isfinite(scale) and scale>0
    run=Run(model,identity,scale);x,status,history,controls=solve(run,x);r,pre,_=model.residual(x);error=norm(r/np.sqrt(pre))/scale
    if error<=1e-8 and all(c['passed'] for c in controls) and status in ('CONVERGED','NEWTON_ALLOWANCE'):status='CONVERGED'
    forces=np.gradient(x[0,:,0],model.r,edge_order=2);rows=[]
    for obs in core.observation_rows():
        g=float(np.interp(obs['R'],model.r,forces));v2=obs['R']*core.A0_V*g;v=math.sqrt(v2) if v2>=0 else None;rows.append(dict(obs,radial_force_a0=g,velocity_squared=v2,model_velocity=v,residual=None if v is None else v-obs['velocity']))
    case=dict(identity=identity,status=status,numerical_residual=finite(error),numerical_residual_reason=None if math.isfinite(error) else 'Nonfinite normalized residual; raw final fields retained',history=history,controls=controls,rows=rows,native_trials=run.native_trials,native_D_failure_checkpoints=run.D_failures,own_checkpoints=RECORDS,parent_case=parent,readout_qualified=False,physical_flags=PHYSICAL)
    checkpoint('FINAL',dict(state=x,residual=r,pre=pre),dict(kind='final_state',identity=identity,status=status,history=history));case['own_checkpoints']=list(RECORDS)
    publish(STEM+'_E1em05_HI0_H20_CASE.json',case);recheck()
    rh=publish(STEM+'_RESULT.json',dict(status=status,manifest=manifest,cases=[case],qualification=PHYSICAL,elapsed_seconds=time.monotonic()-tick))
    p=BASE/(STEM+'_REPORT.md');raw=('# Native-eliminated original FE recovery\n\n'+status+'; one preserved terminal parent case; no physical/refinement/stability/joint certificate.\n').encode()
    with p.open('xb') as f:f.write(raw);f.flush();os.fsync(f.fileno())
    p.chmod(0o444);assert p.read_bytes()==raw;CREATED[p.name]=sha(p);recheck()
    publish(STEM+'_RECEIPT.json',dict(status='CLOSED',owner=OWNER,closed=now(),input_sha256=inputs(),output_sha256=dict(CREATED),result_sha256=rh,qualification=PHYSICAL));recheck();return 0 if status=='CONVERGED' else 3

